-- HoloKai V17.1 PGVector dataset
-- Embeddings are intentionally NULL: populate with your selected embedding model.
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS holokai_v17_1_chunks (
  id TEXT PRIMARY KEY,
  content TEXT NOT NULL,
  metadata JSONB NOT NULL,
  embedding VECTOR(1536)
);

CREATE INDEX IF NOT EXISTS holokai_v17_1_chunks_metadata_gin
  ON holokai_v17_1_chunks USING GIN (metadata);


-- After populating embeddings, add an HNSW index appropriate to your vector dimension/model.
